package dev.aivillages.core.kernel.production.planning;

import java.util.*;
import dev.aivillages.core.kernel.*;
import dev.aivillages.core.kernel.production.*;
import static dev.aivillages.core.kernel.Contracts.*;
import static dev.aivillages.core.kernel.production.planning.PlanningModel.*;

/** Pure useful-checkpoint selection. A must admit, publish, execute and settle every proposed action. */
public final class PlanningCoordinator {
    private final StaticProductionPlanner planner=new StaticProductionPlanner();
    private static String signature(Snapshot s,String segment){var value=new TreeMap<String,Object>();value.put("goal",s.goal().digest());value.put("credit",s.confirmedCredit());value.put("worldRevision",s.relevantWorldRevision());value.put("owner",s.owner().toString());value.put("facility",String.valueOf(s.facility()));value.put("segmentOrBlocker",segment);
        value.put("stock",s.stock().stream().sorted(Comparator.comparing(Stock::key)).map(x->Map.of("key",x.key(),"location",x.location().toString(),"item",x.item().value(),"units",x.units(),"observed",x.observedUnits(),"eligible",x.rootEligibleUnits(),"origin",x.eligibility().name(),"availability",x.availability().name(),"permitted",x.permitted(),"reachable",x.reachable())).toList());
        value.put("methods",s.recipes().stream().map(r->r.recipe()+":"+r.semanticFingerprint()+":"+r.method()).sorted().toList());value.put("acquisition",s.acquisition().stream().map(Object::toString).sorted().toList());value.put("kinds",s.supportedKinds().stream().map(Enum::name).sorted().toList());
        // Epoch-only reloads are not physical progress. Semantic/grid/binding changes remain visible.
        value.put("choices",s.choices().stream().map(o->o.choice().semanticFingerprint()+":"+o.choice().capability()+":"+o.choice().demand()+":"+o.choice().batches()).sorted().toList());return digest(value);}
    private static String budgetProblem(Snapshot s,Memory m){if(m.originalBudgetDigest().isEmpty())return "";if(!m.originalBudgetDigest().equals(s.budget().initialDigest()) || m.originalDeadlineMillis()!=s.budget().absoluteDeadlineMillis())return "ORIGINAL_BUDGET_OR_DEADLINE_CHANGED";for(var c:Counter.values())if(s.budget().used().get(c)<m.observedUsage().get(c))return "CUMULATIVE_USAGE_REGRESSED";return s.returnsUsed()<m.returnsUsed()?"CUSTODY_RETURN_COUNT_REGRESSED":"";}
    private static Memory remember(Snapshot s,String sig,String proposal,int checks,long next){return new Memory(sig,proposal,checks,next,s.budget().initialDigest(),s.budget().absoluteDeadlineMillis(),s.budget().used(),s.returnsUsed());}
    private static long checkAt(Snapshot s,int checks){if(checks>=4)return Long.MAX_VALUE;long delay=250L<<Math.min(checks,3);return Math.min(s.budget().absoluteDeadlineMillis(),s.nowMillis()>Long.MAX_VALUE-delay?Long.MAX_VALUE:s.nowMillis()+delay);}
    private static Decision stop(Snapshot s,Memory old,Analysis analysis,String blocker,ChoiceRequest request){String sig=signature(s,blocker);boolean unchanged=sig.equals(old.signature());int checks=unchanged?Math.min(4,old.unchangedChecks()+1):0;long next=checkAt(s,checks);return new Decision(unchanged?DecisionKind.WAIT:DecisionKind.BLOCKED,checks>=4?"NO_PROGRESS_UNTIL_RELEVANT_CHANGE":blocker,analysis,null,request,remember(s,sig,old.lastProposalId(),checks,next),next);}
    private static Map<Counter,Long> allowance(Cost cost,Snapshot s,Memory memory,boolean newPlan){var out=new EnumMap<Counter,Long>(Counter.class);out.putAll(zeroCounts());out.put(Counter.TRAVEL,cost.travel());out.put(Counter.EFFECTS,cost.effects());out.put(Counter.ELAPSED_TICKS,cost.ticks());out.put(Counter.RETRIES,s.owner().retryRequired()?1L:0L);out.put(Counter.REPLANS,newPlan && !memory.lastProposalId().isEmpty()?1L:0L);for(var c:Counter.values())if(out.get(c)>s.budget().remaining(c))return null;return Map.copyOf(out);}
    private static boolean group(Action a,Action b){return a.kind()==b.kind() && a.recipe().equals(b.recipe()) && a.capability().equals(b.capability()) && a.inputs().equals(b.inputs()) && a.result().equals(b.result()) && a.rootOutput()==b.rootOutput() && a.sourceKey().equals(b.sourceKey());}
    static MethodPin outputMethod(Snapshot s,RecipeChoice.ItemKey item){for(var p:s.recipes())if(p.result().equals(item) && p.method()!=null && p.method().usable())return p.method();for(var a:s.acquisition())if(a.result().equals(item) && a.method()!=null && a.method().usable())return a.method();return null;}
    private static MethodPin method(Snapshot s,Action a){if(a.kind()==Kind.PRODUCE)return s.recipe(a.recipe()).orElseThrow().method();if(a.kind()==Kind.ACQUIRE)return s.acquisition().stream().filter(x->x.key().equals(a.sourceKey())).findFirst().orElseThrow().method();if(a.kind()==Kind.RETURN_CUSTODY)return outputMethod(s,a.result());return s.facility()==null?null:s.facility().placement();}
    private static boolean matches(Snapshot s,Action a,int batches,long amount,ContainerRef destination,ChoiceOffer offer){var c=offer.choice();var p=s.recipe(a.recipe()).orElseThrow();
        if(!c.capability().equals(a.capability()) || !c.recipe().equals(a.recipe()) || c.demand()!=amount || c.batches().size()!=batches || !c.semanticFingerprint().equals(p.semanticFingerprint()) || !offer.request().context().equals(s.context())
                || !(offer.request().request().arguments().get("actor") instanceof ActorValue actor) || !actor.value().equals(s.owner().executor()) || !(offer.request().request().arguments().get("destination") instanceof ContainerValue target) || !target.value().equals(destination) || !s.goal().policy().allowedSources().containsAll(offer.sources().containers()))return false;
        if(p.axe() && (s.facility()==null || c.facility()==null || !c.facility().reference().equals(s.facility().reference()) || !c.facility().identity().equals(s.facility().identity())))return false;
        var expected=new HashMap<RecipeChoice.ItemKey,Long>();a.inputs().forEach((k,n)->expected.put(k,Math.multiplyExact(n,batches)));if(!expected.equals(c.exactInputs()))return false;
        var free=new HashMap<String,Long>();var observed=new HashMap<String,Long>();for(var x:s.stock()){free.put(x.key(),x.units());observed.put(x.key(),x.observedUnits());}
        for(var batch:c.batches()){var ordered=batch.grid().stream().filter(k->!k.empty()).toList();if(ordered.size()!=p.cells().size())return false;for(int i=0;i<ordered.size();i++)if(!p.cells().get(i).contains(ordered.get(i)))return false;
            for(var binding:batch.bindings()){var stock=s.stock().stream().filter(x->x.location().container()!=null && x.location().container().equals(binding.source()) && x.location().slot()==binding.sourceSlot() && x.item().equals(binding.item()) && StaticProductionPlanner.usable(s,x)).findFirst().orElse(null);
                if(stock==null || free.get(stock.key())<1 || observed.get(stock.key())!=binding.expectedCount())return false;free.put(stock.key(),free.get(stock.key())-1);observed.put(stock.key(),observed.get(stock.key())-1);}}
        return true;}
    private static boolean choiceStock(ChoiceOffer offer,Stock stock){return stock.location().container()!=null && offer.choice().batches().stream().flatMap(b->b.bindings().stream()).anyMatch(b->stock.location().container().equals(b.source()) && stock.location().slot()==b.sourceSlot() && stock.item().equals(b.item()));}
    private static long offerTravel(Snapshot s,ChoiceOffer offer){long total=0;for(var x:s.stock())if(choiceStock(offer,x))total=Math.addExact(total,x.travelCost());return total;}
    private static SegmentProposal proposal(Snapshot s,Kind kind,CapabilityId cap,MethodPin method,List<String> actions,List<String> stockKeys,ContainerRef destination,FacilityRef facility,ChoiceOffer choice,Quantities q,Map<Counter,Long> allowance,Checkpoint checkpoint,String planDigest,String acquisitionKey){
        String step="proposal-step:"+digest(Map.of("root",s.root().toString(),"plan",planDigest,"kind",kind.name(),"actions",actions,"stock",stockKeys,"credit",s.confirmedCredit(),"demand",q.requestedDemand()));
        String id=digest(Map.of("step",step,"revision",s.revision(),"generation",s.owner().executionGeneration(),"choice",choice==null?"":choice.choice().digest(),"destination",String.valueOf(destination)));
        var bindings=new ArrayList<StockBinding>();for(var key:stockKeys){var lot=s.stock().stream().filter(x->x.key().equals(key)).findFirst().orElseThrow();long units=choice==null?(kind==Kind.PLACE_TABLE?1:q.requestedDemand()):choice.choice().batches().stream().flatMap(b->b.bindings().stream()).filter(b->lot.location().container()!=null && lot.location().container().equals(b.source()) && lot.location().slot()==b.sourceSlot() && lot.item().equals(b.item())).count();bindings.add(new StockBinding(key,lot.location(),lot.item(),units,lot.observedUnits()));}
        var area=acquisitionKey.isEmpty()?null:s.acquisition().stream().filter(a->a.key().equals(acquisitionKey)).findFirst().orElseThrow().source();
        return new SegmentProposal(SCHEMA,id,step,s.world(),s.root(),s.revision(),s.owner().originalOwner(),s.context(),s.owner().executor(),s.owner().executionGeneration(),kind,cap,method,actions,bindings,acquisitionKey,area,destination,facility,choice,q,allowance,s.budget().absoluteDeadlineMillis(),checkpoint);
    }
    private static Decision offered(Snapshot s,Memory memory,Analysis analysis,SegmentProposal proposal){String sig=signature(s,proposal.stepToken());if(sig.equals(memory.signature()) && !memory.lastProposalId().isEmpty()){int checks=Math.min(4,memory.unchangedChecks()+1);long next=checkAt(s,checks);return new Decision(DecisionKind.WAIT,checks>=4?"NO_PROGRESS_UNTIL_RELEVANT_CHANGE":"AWAITING_AUTHORITATIVE_PROGRESS",analysis,null,null,remember(s,sig,memory.lastProposalId(),checks,next),next);}return new Decision(DecisionKind.PROPOSE,"",analysis,proposal,null,remember(s,sig,proposal.proposalId(),0,0),0);}
    public Decision next(Snapshot s,ValidatedPlan saved,Memory memory){Objects.requireNonNull(memory);String boundary=StaticProductionPlanner.boundaryProblem(s);if(!boundary.isEmpty())return stop(s,memory,null,boundary,null);String budget=budgetProblem(s,memory);if(!budget.isEmpty())return stop(s,memory,null,budget,null);
        if(s.remainingDemand()==0)return new Decision(DecisionKind.GOAL_ALREADY_CREDITED,"AUTHORITATIVE_CREDIT_ALREADY_COVERS_DEMAND",null,null,null,remember(s,signature(s,"credited"),memory.lastProposalId(),0,Long.MAX_VALUE),Long.MAX_VALUE);
        var analysis=saved==null?planner.analyse(s):planner.revalidate(s,saved);if(analysis.feasibility()!=Feasibility.FEASIBLE)return stop(s,memory,analysis,analysis.reason(),null);var plan=analysis.plan();boolean newPlan=saved==null;
        var current=s.stock().stream().filter(x->StaticProductionPlanner.eligibleIn(s,x)>0).sorted(Comparator.comparingLong(Stock::travelCost).thenComparing(Stock::key)).toList();
        if(!current.isEmpty()){var stock=current.getFirst();long amount=Math.min(Math.min(StaticProductionPlanner.eligibleIn(s,stock),s.remainingDemand()),s.goal().policy().carryingUnits());boolean atDestination=s.activeDestination().equals(stock.location().container());Kind kind=atDestination?Kind.ALLOCATE_CURRENT:Kind.DELIVER_CURRENT;
            if(!s.supportedKinds().contains(kind))return stop(s,memory,analysis,"CURRENT_DELIVERY_OR_ALLOCATION_ADAPTER_UNSUPPORTED",null);var pin=atDestination?null:outputMethod(s,stock.item());if(!atDestination && pin==null)return stop(s,memory,analysis,"PINNED_DELIVERY_METHOD_UNAVAILABLE",null);
            var allowed=allowance(atDestination?Cost.ZERO:new Cost(stock.travelCost(),1,1),s,memory,newPlan);if(allowed==null)return stop(s,memory,analysis,"CUMULATIVE_SEGMENT_LIMIT_EXHAUSTED",null);
            var q=new Quantities(amount,0,0,amount,atDestination?0:amount,amount,0,0,0);var checkpoint=new Checkpoint(atDestination?Predicate.CURRENT_AUTHORIZED_ALLOCATION:Predicate.CONFIRMED_DELIVERY_DELTA,stock.item(),amount,s.activeDestination(),null);
            return offered(s,memory,analysis,proposal(s,kind,pin==null?null:pin.capability(),pin,List.of(),List.of(stock.key()),s.activeDestination(),null,null,q,allowed,checkpoint,plan.digest(),""));}
        int first=-1;for(int i=0;i<plan.actions().size();i++)if(!s.settledActionTokens().contains(plan.actions().get(i).token(i))){first=i;break;}if(first<0)return stop(s,memory,analysis,"CURRENT_PROGRESS_REQUIRES_AUTHORITY_RECONCILIATION",null);
        var a=plan.actions().get(first);int count=1;long demand=a.requestedDemand(),inputUnits=a.inputs().values().stream().mapToLong(Long::longValue).sum();long carryBatches=s.goal().policy().carryingUnits()/Math.max(1,Math.max(inputUnits,a.yield()));
        if(carryBatches<1)return stop(s,memory,analysis,"CURRENT_CARRYING_CAPACITY_INSUFFICIENT",null);int maximum=a.kind()==Kind.PRODUCE?definition(a.capability()).maximumBatches():a.kind()==Kind.ACQUIRE?64:1;
        for(int i=first+1;i<plan.actions().size() && count<carryBatches && count<maximum;i++){var next=plan.actions().get(i);if(!group(a,next) || s.settledActionTokens().contains(next.token(i)))break;count++;demand=Math.addExact(demand,next.requestedDemand());}
        var tokens=new ArrayList<String>();for(int i=0;i<count;i++)tokens.add(plan.actions().get(first+i).token(first+i));var pin=method(s,a);if(pin==null || !pin.usable())return stop(s,memory,analysis,s.modelAvailable() && s.budget().remaining(Counter.MODEL_CALLS)>0?"EXISTING_AUTHORIZED_ADMISSION_REQUIRED":"PINNED_METHOD_UNAVAILABLE_OFFLINE",null);
        long physical=Math.multiplyExact((long)a.yield(),count),nativeAmount=a.rootOutput()?demand:physical;ContainerRef destination=a.rootOutput()?s.activeDestination():s.goal().policy().staging();ChoiceOffer choice=null;
        if(a.kind()==Kind.PRODUCE){final int n=count;final long amount=nativeAmount;choice=s.choices().stream().filter(o->matches(s,a,n,amount,destination,o)).sorted(Comparator.comparingLong((ChoiceOffer o)->offerTravel(s,o)).thenComparing(o->o.choice().digest())).findFirst().orElse(null);
            if(choice==null)return stop(s,memory,analysis,"FRESH_EXACT_NATIVE_CHOICE_REQUIRED",new ChoiceRequest(a.capability(),nativeAmount,destination,s.recipe(a.recipe()).orElseThrow().semanticFingerprint(),s.goal().policy().allowedSources().stream().sorted(Comparator.comparing(Object::toString)).toList()));}
        var allowed=allowance(a.allowance().times(count),s,memory,newPlan);if(allowed==null)return stop(s,memory,analysis,"CUMULATIVE_SEGMENT_LIMIT_EXHAUSTED",null);
        long goal=a.rootOutput()?demand:0,parent=a.rootOutput()?0:demand,unallocated=physical-demand,actorSurplus=physical-nativeAmount,existing=0;
        if(a.kind()==Kind.PLACE_TABLE){goal=0;parent=0;unallocated=0;actorSurplus=0;nativeAmount=0;existing=1;}
        if(a.kind()==Kind.RETURN_CUSTODY){goal=0;parent=0;unallocated=demand;actorSurplus=0;nativeAmount=demand;existing=demand;}
        var q=new Quantities(demand,a.kind()==Kind.RETURN_CUSTODY?0:count,physical,existing,nativeAmount,goal,parent,unallocated,actorSurplus);final ChoiceOffer selected=choice;
        List<String> stockKeys=selected==null?List.of():s.stock().stream().filter(x->choiceStock(selected,x)).map(Stock::key).sorted().toList();
        if(a.kind()==Kind.PLACE_TABLE){var tableStock=s.stock().stream().filter(x->StaticProductionPlanner.usable(s,x) && x.location().container()!=null && a.inputs().containsKey(x.item()) && x.units()>0).sorted(Comparator.comparingLong(Stock::travelCost).thenComparing(Stock::key)).findFirst().orElse(null);if(tableStock==null)return stop(s,memory,analysis,"EXACT_TABLE_SOURCE_BINDING_REQUIRED",null);stockKeys=List.of(tableStock.key());}
        if(a.kind()==Kind.RETURN_CUSTODY)stockKeys=List.of(a.sourceKey());
        Predicate predicate=a.kind()==Kind.PLACE_TABLE?Predicate.CURRENT_FACILITY:a.kind()==Kind.RETURN_CUSTODY?Predicate.CURRENT_RETURNED_CUSTODY:a.rootOutput()?Predicate.CONFIRMED_DELIVERY_DELTA:Predicate.CURRENT_MATERIALS;
        var checkpoint=new Checkpoint(predicate,a.result(),a.kind()==Kind.PLACE_TABLE?1:nativeAmount,destination,a.kind()==Kind.PLACE_TABLE?s.facility().reference():null);
        return offered(s,memory,analysis,proposal(s,a.kind(),a.capability(),pin,tokens,stockKeys,destination,a.kind()==Kind.PLACE_TABLE?s.facility().reference():null,choice,q,allowed,checkpoint,plan.digest(),a.kind()==Kind.ACQUIRE?a.sourceKey():""));
    }
}
